/*
 * A084421  a(n) = A005187(A000040(n)).
 * https://oeis.org/A084421
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (p * 2) - popcount(p) where p = n-th prime (A000040(n))
 * Range:     u8 n <= 31, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence A084421 is generated by computing p_n for n≥1, then
   adding p_n + floor(p_n/2) + floor(p_n/4) + … + 1, which simplifies
   to 2*p_n − popcount(p_n).  This implementation builds the list of
   primes on demand using trial division.  It works for any n≥1 and
   for all reasonably sized n (e.g. up to 10⁶ primes). */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <math.h>

seq_t a(idx_t n)
{
    /* Static storage for computed primes and the next candidate */
    static uint64_t *primes      = NULL;   /* array of found primes */
    static size_t   prime_cnt   = 0;       /* number of primes stored */
    static size_t   prime_cap   = 0;       /* current capacity of the array */
    static uint64_t candidate   = 2;       /* next number to test for primality */

    /* Ensure we have at least n primes precomputed */
    while (prime_cnt < n) {
        /* Expand primes array if necessary */
        if (prime_cap <= prime_cnt) {
            size_t new_cap = prime_cap ? prime_cap * 2 : 32;
            uint64_t *tmp = (uint64_t *)realloc(primes, new_cap * sizeof(uint64_t));
            if (tmp == NULL) {
                /* Memory allocation failed; return 0 as a sentinel */
                return (seq_t)0;
            }
            primes   = tmp;
            prime_cap = new_cap;
        }

        /* Check if current candidate is prime */
        bool is_prime = true;
        if (candidate == 2) {
            /* 2 is prime */
            primes[prime_cnt++] = 2;
            candidate = 3;
            continue;
        }

        /* Skip even numbers */
        if ((candidate & 1ULL) == 0) {
            candidate += 1;
            continue;
        }

        uint64_t root = (uint64_t)sqrt((double)candidate);
        for (size_t i = 0; i < prime_cnt; ++i) {
            uint64_t p = primes[i];
            if (p > root) break;
            if (candidate % p == 0) {
                is_prime = false;
                break;
            }
        }

        if (is_prime) {
            primes[prime_cnt++] = candidate;
        }
        candidate += 2;   /* Move to next odd candidate */
    }

    /* Retrieve the n-th prime (1‑based index) */
    uint64_t p = primes[n - 1];

    /* Compute the sum: 2*p - popcount(p) */
    seq_t result = (seq_t)p * 2ULL - (seq_t)__builtin_popcountll(p);
    return result;
}
